# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Hyperparameters for this iteration
iteration = 1
NUM_SPECIES = 206
BATCH_SIZE = {8 if iteration % 3 == 0 else 16 if iteration % 3 == 1 else 32}
LEARNING_RATE = {0.001 if iteration % 3 == 0 else 0.0001 if iteration % 3 == 1 else 0.00001}
NUM_CONV_LAYERS = {2 if iteration % 3 == 0 else 3 if iteration % 3 == 1 else 4}
DROPOUT_RATE = {0.0 if iteration % 3 == 0 else 0.2 if iteration % 3 == 1 else 0.5}
WEIGHT_DECAY = {0 if iteration % 3 == 0 else 0.0001 if iteration % 3 == 1 else 0.001}

# Data ingestion & augmentation
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader, val_loader = build_train_val_dataloaders(
    metadata_csv=METADATA_FILE,
    audio_dir=DATA_DIR,
    batch_size=BATCH_SIZE,
    augment=True,      # Enable augmentation for training
    val_split=0.2,     # 80/20 split
)

# Model architecture
class BirdClassifier(nn.Module):
    def __init__(self, num_species=NUM_SPECIES, dropout_rate=DROPOUT_RATE):
        super(BirdClassifier, self).__init__()
        conv_layers = []
        in_channels = 1
        
        # Define convolutional layers based on NUM_CONV_LAYERS
        for _ in range(NUM_CONV_LAYERS):
            out_channels = 32 * (len(conv_layers) + 1)
            conv_layers.append(nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1))
            conv_layers.append(nn.BatchNorm2d(out_channels))
            conv_layers.append(nn.ReLU())
            in_channels = out_channels
        
        self.conv_layers = nn.Sequential(*conv_layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Dropout(dropout_rate),
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Instantiate the model
model = BirdClassifier(num_species=NUM_SPECIES, dropout_rate=DROPOUT_RATE)
device = 'cuda' if torch.cuda.is_available() else 'cpu'
model.to(device)

# Loss function and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE, weight_decay=WEIGHT_DECAY)

# Training loop
def train_model(max_epochs=20, early_stopping_patience=5):
    best_auc = 0.0
    early_stopping_counter = 0
    
    for epoch in range(max_epochs):
        model.train()
        total_loss = 0.0
        
        for inputs, labels in tqdm(train_loader):
            inputs, labels = inputs.to(device), labels.to(device)
            
            # Forward pass
            outputs = model(inputs)
            loss = criterion(outputs, labels.float())
            
            # Backward pass and optimization
            optimizer.zero_grad()
            loss.backward()
            optimizer.step()
            
            total_loss += loss.item()
            torch.cuda.empty_cache()  # Prevent GPU fragmentation
        
        avg_train_loss = total_loss / len(train_loader)
        
        # Validation
        model.eval()
        all_preds, all_labels = [], []
        
        with torch.no_grad():
            for inputs, labels in val_loader:
                inputs, labels = inputs.to(device), labels.to(device)
                outputs = model(inputs)
                all_preds.extend(outputs.cpu().numpy())
                all_labels.extend(labels.cpu().numpy())
        
        # Calculate AUC
        auc_score = roc_auc_score(all_labels, all_preds, average='weighted')
        
        print(f"Epoch {epoch+1}/{max_epochs} - Train Loss: {avg_train_loss:.4f}, Val AUC: {auc_score:.4f}")
        
        # Early stopping check
        if auc_score > best_auc:
            best_auc = auc_score
            early_stopping_counter = 0
            torch.save(model.state_dict(), 'model.pt')
        else:
            early_stopping_counter += 1
            if early_stopping_counter >= early_stopping_patience:
                print("Early stopping triggered.")
                break
    
    return avg_train_loss, best_auc

# Run training
final_train_loss, final_auc = train_model()

# Save metrics to JSON
metrics = {
    "final_train_loss": final_train_loss,
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": 20,
    "batch_size": BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))